{
  "selections": [
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/situations/3", "/childhood_data"],
      "relevance": "내담자가 학부모 설명회 설문 30장 중 29장이 '매우 만족'이었음에도 '설명이 다소 빨랐다'는 1장에만 집착하며 새벽까지 복기한 것은, 엄격한 기준과 과잉비판이 작동하는 직접적 장면임. 성장 배경에서 98점을 받아도 '2점은 왜 틀렸냐'는 추궁을 받은 패턴과 구조가 동일함."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/situations/3"],
      "relevance": "29장의 긍정적 결과를 '별거 아닌 건가요?'라고 스스로 묻는 것 자체가, 아무리 잘해도 충분하지 않다는 핵심 신념이 작동하고 있음을 보여줌. 상담사가 '별거 아닌 건 아닌 것 같다'고 확인해준 지점과 직접 연결됨."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/situations/3"],
      "relevance": "'설명이 다소 빨랐다'는 사소한 피드백을 그냥 넘기지 못하고 새벽까지 복기하는 행동은, 실수를 어중간하게 넘기는 것을 무책임하게 여기는 태도가 작동한 결과임. 내담자도 '예전엔 안 그랬는데'라고 말하며 이 태도의 강도가 최근 더 강해졌음을 인지하고 있음."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/3"],
      "relevance": "1장의 부정적 설문지를 '결국 구멍이 있었다'는 증거로 해석하고, 완벽하게 준비했다고 생각했는데도 그 한 장이 자기 가치에 대한 위협으로 느껴지는 것은, 기준을 낮추면 사람들이 '그 정도밖에 안 되는 사람'임을 알게 될 것이라는 부정적 가정과 연결됨."
    },
    {
      "trait_id": "/coping_strategies/3",
      "background_ids": ["/situations/3"],
      "relevance": "칭찬 일색인 29장은 넘겨버리고 그 1장만 몇 번이고 다시 읽으며, 새벽까지 진행을 처음부터 복기하는 행동은 '잘된 부분은 깎아내리고 부족했던 부분을 복기하는 데 시간을 쓴다'는 대처 전략의 직접적 발현임."
    }
  ]
}

